'use client';

import { useEffect, useMemo, useState } from 'react';
import { supabase, type BusinessContext } from '@/lib/supabase';
const money=(n:number)=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(Number(n||0));
type Vendor={vendor_id:string;display_name:string;billed:number;paid:number;balance_due:number};
export default function Vendors(){const[rows,setRows]=useState<Vendor[]>([]),[q,setQ]=useState(''),[loading,setLoading]=useState(true);useEffect(()=>{(async()=>{const c=await supabase.rpc('get_my_business_context');const b=c.data?.[0] as BusinessContext|undefined;if(!b){location.href='/';return}const r=await supabase.from('vendor_balances').select('vendor_id,display_name,billed,paid,balance_due').eq('business_id',b.business_id).order('balance_due',{ascending:false});setRows(r.data||[]);setLoading(false)})()},[]);const filtered=useMemo(()=>rows.filter(x=>x.display_name.toLowerCase().includes(q.toLowerCase())),[rows,q]);if(loading)return <div className="grid min-h-[70vh] place-items-center text-sm text-slate-500">Loading vendors…</div>;const payable=rows.reduce((a,x)=>a+Number(x.balance_due||0),0);return <main className="min-h-screen bg-[#fbfaff] p-4 sm:p-6 lg:p-8"><div className="mx-auto max-w-[1250px]"><header className="mb-7 flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div><p className="text-[10px] font-bold uppercase tracking-[.18em] text-violet-600">Money out</p><h1 className="mt-1 text-3xl font-semibold">Vendors</h1><p className="mt-2 text-sm text-slate-500">Know who you owe, what you bought and what has already been paid.</p></div><button onClick={()=>location.href='/next-workspace/purchases'} className="rounded-xl bg-violet-600 px-4 py-2.5 text-sm font-semibold text-white">Record purchase</button></header><div className="grid gap-4 sm:grid-cols-3"><K title="Vendors" value={String(rows.length)} note="Active supplier balances"/><K title="Amount to pay" value={money(payable)} note="Current payable balance"/><K title="Bills" value={String(rows.filter(x=>Number(x.billed)>0).length)} note="Suppliers with bills"/></div><section className="mt-6 overflow-hidden rounded-2xl border border-slate-200 bg-white"><div className="flex flex-col gap-3 border-b border-slate-100 p-4 sm:flex-row sm:items-center"><div className="relative flex-1"><span className="absolute left-3 top-2.5 text-slate-400">⌕</span><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Search vendors…" className="w-full rounded-xl border border-slate-200 bg-[#fbfaff] py-2.5 pl-9 pr-4 text-sm outline-none"/></div><button onClick={()=>location.href='/next-workspace/purchases'} className="rounded-xl border border-slate-200 px-4 py-2.5 text-xs font-semibold">View purchases</button></div><div className="hidden grid-cols-[1fr_140px_140px_150px] gap-3 border-b border-slate-100 px-5 py-3 text-[10px] font-bold uppercase tracking-wider text-slate-400 sm:grid"><span>Vendor</span><span className="text-right">Billed</span><span className="text-right">Paid</span><span className="text-right">Outstanding</span></div><div className="divide-y divide-slate-100">{filtered.map(v=><button key={v.vendor_id} onClick={()=>location.href='/next-workspace/purchases'} className="grid w-full gap-2 px-4 py-4 text-left hover:bg-violet-50/40 sm:grid-cols-[1fr_140px_140px_150px] sm:items-center sm:gap-3 sm:px-5"><span className="flex items-center gap-3"><span className="grid h-10 w-10 place-items-center rounded-xl bg-violet-50 text-violet-700">V</span><span><b className="block text-sm">{v.display_name}</b><span className="text-xs text-slate-400">Supplier account</span></span></span><span className="text-sm sm:text-right">{money(v.billed)}</span><span className="text-sm sm:text-right">{money(v.paid)}</span><b className="text-sm sm:text-right">{money(v.balance_due)}</b></button>)}{!filtered.length&&<div className="p-10 text-center text-sm text-slate-500">No vendors found.</div>}</div></section></div></main>}
function K({title,value,note}:{title:string;value:string;note:string}){return <section className="rounded-2xl border border-slate-200 bg-white p-5"><span className="text-xs font-semibold text-slate-500">{title}</span><b className="mt-3 block text-2xl tracking-tight">{value}</b><span className="mt-1 block text-xs text-slate-400">{note}</span></section>}
